-- ============================================================================
-- 024_division_j.sql
-- The school's Division J practice set: 200 questions, 9 sets, 46 with figures.
-- Imported from olympiad_division_j_questions.json.
-- Run after 023. Safe to re-run.
-- ============================================================================

alter table problems add column if not exists source_ref text;

values ('APSMO Division J', 'apsmo', 141, 160,
        'School practice set, from Maths Olympiad Contest Problems Vol 2 · Division J. 9 sets, 200 questions.')
on conflict (exam) do nothing;

on conflict (chapter, idx) do nothing;
on conflict (chapter, idx) do nothing;
on conflict (chapter, idx) do nothing;
on conflict (chapter, idx) do nothing;
on conflict (chapter, idx) do nothing;
on conflict (chapter, idx) do update set answer_key = excluded.answer_key, method = excluded.method, answer = excluded.answer, verified = true;
on conflict (chapter, idx) do update set answer_key = excluded.answer_key, method = excluded.method, answer = excluded.answer, verified = true;
on conflict (chapter, idx) do update set answer_key = excluded.answer_key, method = excluded.method, answer = excluded.answer, verified = true;
on conflict (chapter, idx) do update set answer_key = excluded.answer_key, method = excluded.method, answer = excluded.answer, verified = true;

select 'APSMO Division J', chapter, idx from problems where source = 'apsmo'
on conflict do nothing;

update chapters set practice = (select count(*) from problems p where p.chapter = chapters.n)
 where n between 141 and 160;

