  (141,8,$q$The number 6 has exactly four factors: 1, 2, 3 and 6. How many different factors does 36 have?$q$,2,array['Set 1']::text[],'apsmo',null,'S1-4C'),
  (141,9,$q$A car takes 1 minute 30 seconds to travel 1 kilometre. At this rate, how many kilometres does it travel in 1 hour?$q$,2,array['Set 1']::text[],'apsmo',null,'S1-4D'),
  (141,10,$q$At a sale all pens cost one price and all pencils another. 3 pens and 2 pencils cost 47c; 2 pens and 3 pencils cost 38c. What does one pen and one pencil cost together?$q$,3,array['Set 1']::text[],'apsmo',null,'S1-4E'),
  (141,11,$q$Zeros at the end of a number are called terminal zeros (203 500 has two). How many terminal zeros does 30 × 40 × 50 × 60 × 70 have?$q$,1,array['Set 1']::text[],'apsmo',null,'S1-5A'),
  (141,12,$q$Square ACEG has midpoints B, D, F, H on its sides. Both diagonals, the lines BF and HD, and the square BDFH are drawn. How many squares of all sizes can be traced using only these lines?$q$,3,array['Set 1']::text[],'apsmo',$q$<svg viewBox="0 0 200 200" width="200" height="200" xmlns="http://www.w3.org/2000/svg" font-family="Georgia,serif" font-size="13"><rect x="30" y="25" width="140" height="140" fill="none" stroke="#1f2130" stroke-width="1.8"/><line x1="30" y1="25" x2="170" y2="165" stroke="#1f2130" stroke-width="1.6"/><line x1="170" y1="25" x2="30" y2="165" stroke="#1f2130" stroke-width="1.6"/><line x1="100.0" y1="25" x2="100.0" y2="165" stroke="#1f2130" stroke-width="1.6"/><line x1="30" y1="95.0" x2="170" y2="95.0" stroke="#1f2130" stroke-width="1.6"/><line x1="100.0" y1="25" x2="170" y2="95.0" stroke="#1f2130" stroke-width="1.6"/><line x1="170" y1="95.0" x2="100.0" y2="165" stroke="#1f2130" stroke-width="1.6"/><line x1="100.0" y1="165" x2="30" y2="95.0" stroke="#1f2130" stroke-width="1.6"/><line x1="30" y1="95.0" x2="100.0" y2="25" stroke="#1f2130" stroke-width="1.6"/><text x="22" y="19" text-anchor="middle" font-size="13" font-style="italic">A</text><text x="100.0" y="17" text-anchor="middle" font-size="13" font-style="italic">B</text><text x="178" y="19" text-anchor="middle" font-size="13" font-style="italic">C</text><text x="182" y="99.0" text-anchor="middle" font-size="13" font-style="italic">D</text><text x="178" y="181" text-anchor="middle" font-size="13" font-style="italic">E</text><text x="100.0" y="183" text-anchor="middle" font-size="13" font-style="italic">F</text><text x="22" y="181" text-anchor="middle" font-size="13" font-style="italic">G</text><text x="18" y="99.0" text-anchor="middle" font-size="13" font-style="italic">H</text></svg>$q$,'S1-5B'),
  (141,13,$q$Megan has A quarters (25c) and B dimes (10c), worth $1.95 altogether, with A and B both at least 1. How many different values can A have?$q$,2,array['Set 1']::text[],'apsmo',null,'S1-5C'),
  (141,14,$q$On a normal 12-hour clock, 12 and 6 are opposite. On planet Bajor the clock has the numbers 1 to 10 equally spaced. Which pair of opposite numbers on a Bajorian clock adds to 11?$q$,3,array['Set 1']::text[],'apsmo',null,'S1-5D'),
  (141,15,$q$Gil spends ⅓ of his money in store A, then ⅓ of what is left in store B, and finally his remaining $12 in store C. How much did he start with?$q$,3,array['Set 1']::text[],'apsmo',null,'S1-5E'),
  (142,1,$q$Find the value of 9 + 91 + 18 + 82 + 27 + 73 + 36 + 64 + 45 + 55.$q$,1,array['Set 2']::text[],'apsmo',null,'S2-1A'),
