  (144,5,$q$A normal duck has two legs, a lame duck one, a sitting duck none. Donald has 33 ducks: two more normal than lame, and two more lame than sitting. How many legs do they have in all?$q$,3,array['Set 4']::text[],'apsmo',null,'S4-1E'),
  (144,6,$q$Roberta throws five darts at the target (rings score 2, 4, 6, 8, 10) and every dart lands on the target. Which of these totals are NOT possible: 6, 14, 17, 38, 42, 58?$q$,2,array['Set 4']::text[],'apsmo',$q$<svg viewBox="0 0 200 200" width="200" height="200" xmlns="http://www.w3.org/2000/svg" font-family="Georgia,serif" font-size="13"><circle cx="100.0" cy="100.0" r="92" fill="#e9e7f8" stroke="#1f2130" stroke-width="1.6"/><circle cx="100.0" cy="100.0" r="74" fill="#fff" stroke="#1f2130" stroke-width="1.6"/><circle cx="100.0" cy="100.0" r="56" fill="#e9e7f8" stroke="#1f2130" stroke-width="1.6"/><circle cx="100.0" cy="100.0" r="38" fill="#fff" stroke="#1f2130" stroke-width="1.6"/><circle cx="100.0" cy="100.0" r="20" fill="#e9e7f8" stroke="#1f2130" stroke-width="1.6"/><text x="100.0" y="22" text-anchor="middle" font-size="13" font-weight="bold">2</text><text x="100.0" y="40" text-anchor="middle" font-size="13" font-weight="bold">4</text><text x="100.0" y="58" text-anchor="middle" font-size="13" font-weight="bold">6</text><text x="100.0" y="76" text-anchor="middle" font-size="13" font-weight="bold">8</text><text x="100.0" y="105" text-anchor="middle" font-size="13" font-weight="bold">10</text></svg>$q$,'S4-2A'),
  (144,7,$q$Kelly paid $20 for a CD and got $6 change, then paid $15 for a bracelet and got $3 change. She then had $28. How much did she have before?$q$,1,array['Set 4']::text[],'apsmo',null,'S4-2B'),
  (144,8,$q$On a 100 cm measuring stick there are marks at 19 cm, N and 99 cm (left to right). The distance from N to 99 is three times the distance from 19 to N. What is N?$q$,2,array['Set 4']::text[],'apsmo',null,'S4-2C'),
  (144,9,$q$The object is made of six congruent cubes: a row of four with one more cube on top of each end. All outer faces, including the bottom, are painted blue. How many cube faces are painted?$q$,2,array['Set 4']::text[],'apsmo',$q$<svg viewBox="0 0 129 133" width="129" height="133" xmlns="http://www.w3.org/2000/svg" font-family="Georgia,serif" font-size="13"><polygon points="98.1,86.0 120.6,73.0 120.6,47.0 98.1,60.0" fill="#e4e1f6" stroke="#1f2130" stroke-width="1"/><polygon points="98.1,34.0 120.6,21.0 98.1,8.0 75.5,21.0" fill="#ffffff" stroke="#1f2130" stroke-width="1"/><polygon points="98.1,60.0 120.6,47.0 120.6,21.0 98.1,34.0" fill="#e4e1f6" stroke="#1f2130" stroke-width="1"/><polygon points="98.1,60.0 75.5,47.0 75.5,21.0 98.1,34.0" fill="#c9c4ec" stroke="#1f2130" stroke-width="1"/><polygon points="75.5,73.0 98.1,60.0 75.5,47.0 53.0,60.0" fill="#ffffff" stroke="#1f2130" stroke-width="1"/><polygon points="75.5,99.0 98.1,86.0 98.1,60.0 75.5,73.0" fill="#e4e1f6" stroke="#1f2130" stroke-width="1"/><polygon points="53.0,86.0 75.5,73.0 53.0,60.0 30.5,73.0" fill="#ffffff" stroke="#1f2130" stroke-width="1"/><polygon points="53.0,112.0 75.5,99.0 75.5,73.0 53.0,86.0" fill="#e4e1f6" stroke="#1f2130" stroke-width="1"/><polygon points="30.5,125.0 53.0,112.0 53.0,86.0 30.5,99.0" fill="#e4e1f6" stroke="#1f2130" stroke-width="1"/><polygon points="30.5,125.0 8.0,112.0 8.0,86.0 30.5,99.0" fill="#c9c4ec" stroke="#1f2130" stroke-width="1"/><polygon points="30.5,73.0 53.0,60.0 30.5,47.0 8.0,60.0" fill="#ffffff" stroke="#1f2130" stroke-width="1"/><polygon points="30.5,99.0 53.0,86.0 53.0,60.0 30.5,73.0" fill="#e4e1f6" stroke="#1f2130" stroke-width="1"/><polygon points="30.5,99.0 8.0,86.0 8.0,60.0 30.5,73.0" fill="#c9c4ec" stroke="#1f2130" stroke-width="1"/></svg>$q$,'S4-2D'),
  (144,10,$q$The post office sells only 3c and 8c stamps. What is the greatest whole-cent postage that cannot be made?$q$,3,array['Set 4']::text[],'apsmo',null,'S4-2E'),
  (144,11,$q$Sandy writes every whole number from 1 to 100. How many times does she write the digit 2?$q$,1,array['Set 4']::text[],'apsmo',null,'S4-3A'),
  (144,12,$q$Paul has half as many lollies as Jennifer. Jennifer has half as many as Charles. Charles has 12 times as many as Susan, who has 4. How many do Charles and Paul have together?$q$,1,array['Set 4']::text[],'apsmo',null,'S4-3B'),
  (144,13,$q$Consider every pair of counting numbers (they may be equal) whose sum is less than 11. How many different products are possible?$q$,2,array['Set 4']::text[],'apsmo',null,'S4-3C'),
  (144,14,$q$Mary and Kevin each have a 36 m² rectangular garden with whole-metre sides. Mary's is 1 m wider than Kevin's, but Kevin's is 3 m longer than Mary's. How wide is Mary's garden?$q$,3,array['Set 4']::text[],'apsmo',null,'S4-3D'),
  (144,15,$q$Eight traffic lights each stay green for 2 minutes. They turn green 10 seconds apart from the first to the eighth. How long are all eight green at the same time?$q$,3,array['Set 4']::text[],'apsmo',null,'S4-3E')
insert into problems (chapter, idx, prompt, difficulty, technique_tags, source, diagram_svg, source_ref) values
  (144,16,$q$PQ and RS are two-digit numbers using four different digits from 6, 7, 8 and 9. What is the greatest possible PQ × RS?$q$,1,array['Set 4']::text[],'apsmo',null,'S4-4A'),
  (144,17,$q$Ten counters are numbered 1–10. Gina and Monique each take 5. Gina has 2 and 8; Monique has 7 and 9. What is the largest sum Gina's counters can have?$q$,1,array['Set 4']::text[],'apsmo',null,'S4-4B'),
  (144,18,$q$A fast clock gains time at a steady rate. It is set correctly at 10 a.m. When it shows 11 a.m., the true time is 10:52. When it shows 3:30 p.m., what is the true time?$q$,2,array['Set 4']::text[],'apsmo',null,'S4-4C'),
  (144,19,$q$Counting numbers are arranged in a triangle: row 1 is 1; row 2 is 2 3 4; row 3 is 5–9; row 4 is 10–16, and so on. What is the first number in row 13?$q$,3,array['Set 4']::text[],'apsmo',$q$<svg viewBox="0 0 260 145" width="260" height="145" xmlns="http://www.w3.org/2000/svg" font-family="Georgia,serif" font-size="13"><text x="130.0" y="26" text-anchor="middle" font-size="14" >1</text><text x="100.0" y="52" text-anchor="middle" font-size="14" >2</text><text x="130.0" y="52" text-anchor="middle" font-size="14" >3</text><text x="160.0" y="52" text-anchor="middle" font-size="14" >4</text><text x="70.0" y="78" text-anchor="middle" font-size="14" >5</text><text x="100.0" y="78" text-anchor="middle" font-size="14" >6</text><text x="130.0" y="78" text-anchor="middle" font-size="14" >7</text><text x="160.0" y="78" text-anchor="middle" font-size="14" >8</text><text x="190.0" y="78" text-anchor="middle" font-size="14" >9</text><text x="40.0" y="104" text-anchor="middle" font-size="14" >10</text><text x="70.0" y="104" text-anchor="middle" font-size="14" >11</text><text x="100.0" y="104" text-anchor="middle" font-size="14" >12</text><text x="130.0" y="104" text-anchor="middle" font-size="14" >13</text><text x="160.0" y="104" text-anchor="middle" font-size="14" >14</text><text x="190.0" y="104" text-anchor="middle" font-size="14" >15</text><text x="220.0" y="104" text-anchor="middle" font-size="14" >16</text><text x="240" y="135" text-anchor="end" font-size="12" font-style="italic">… and so on</text></svg>$q$,'S4-4D'),
  (144,20,$q$A 14-digit number N has 8 as its first and last digit, with 793 written four times in between. What is the remainder when N is divided by 7?$q$,3,array['Set 4']::text[],'apsmo',null,'S4-4E'),
  (144,21,$q$In the addition 6B52 + 9C4 + A37D = 11111, different letters are different digits. Find A, B, C and D.$q$,1,array['Set 4']::text[],'apsmo',$q$<svg viewBox="0 0 190 134" width="190" height="134" xmlns="http://www.w3.org/2000/svg" font-family="Georgia,serif" font-size="13"><text x="170" y="30" text-anchor="end" font-size="20" font-style="italic" xml:space="preserve">6 B 5 2</text><text x="170" y="58" text-anchor="end" font-size="20" font-style="italic" xml:space="preserve">  9 C 4</text><text x="170" y="86" text-anchor="end" font-size="20" font-style="italic" xml:space="preserve">+ A 3 7 D</text><line x1="70" y1="94" x2="175" y2="94" stroke="#1f2130" stroke-width="1.8"/><text x="170" y="122" text-anchor="end" font-size="20" >1 1 1 1 1</text></svg>$q$,'S4-5A'),
  (144,22,$q$AB and BA are two-digit numbers with the same digits reversed. Their difference is 54 and A + B = 10. Find both numbers.$q$,1,array['Set 4']::text[],'apsmo',null,'S4-5B'),
  (144,23,$q$Two rectangles overlap: 7 cm × 5 cm and 10 cm × 8 cm. The top of the larger is 3 cm below the top of the smaller, and its right side is 6 cm beyond the smaller's right side. What is the total area of the shaded (non-overlapping) parts?$q$,2,array['Set 4']::text[],'apsmo',$q$<svg viewBox="0 0 260 260" width="260" height="260" xmlns="http://www.w3.org/2000/svg" font-family="Georgia,serif" font-size="13"><rect x="20" y="30" width="112" height="80" fill="#cfcbee" stroke="#1f2130" stroke-width="1.8"/><rect x="68" y="78" width="160" height="128" fill="#cfcbee" stroke="#1f2130" stroke-width="1.8"/><rect x="68" y="78" width="64" height="32" fill="#fff" stroke="#1f2130" stroke-width="1.8"/><text x="76.0" y="24" text-anchor="middle" font-size="13" >7</text><text x="12" y="74.0" text-anchor="middle" font-size="13" >5</text><text x="140" y="58.0" text-anchor="middle" font-size="13" >3</text><text x="180" y="72" text-anchor="middle" font-size="13" >6</text><text x="238" y="146" text-anchor="middle" font-size="13" >8</text><text x="148" y="222" text-anchor="middle" font-size="13" >10</text></svg>$q$,'S4-5C'),
  (144,24,$q$How many counting numbers less than 200 are divisible by 6 or by 9 or both?$q$,3,array['Set 4']::text[],'apsmo',null,'S4-5D'),
  (144,25,$q$How many terminal zeros (zeros at the very end) does 1 × 2 × 3 × … × 30 have?$q$,3,array['Set 4']::text[],'apsmo',null,'S4-5E'),
  (145,1,$q$To engrave a word, each of the first three letters costs 5 cents, and each letter after that costs 1 cent more than the one before. What does it cost to engrave OLYMPIADS?$q$,1,array['Set 5']::text[],'apsmo',null,'S5-1A'),
  (145,2,$q$Jean, Krisha and Lisa practise at different times: 10 a.m., noon and 2 p.m. Jean practises at noon or 2 p.m. Krisha doesn't practise at noon. Lisa doesn't practise at 2 p.m. Krisha practises 2 hours before Lisa. When does each girl practise?$q$,2,array['Set 5']::text[],'apsmo',null,'S5-1B'),
  (145,3,$q$Find the smallest counting number that leaves remainder 1 when divided by 6 and remainder 6 when divided by 11.$q$,2,array['Set 5']::text[],'apsmo',null,'S5-1C'),
  (145,4,$q$The figure is six congruent squares: a row of three, one above the right-hand square and one below the left-hand square. Its area is 96 cm². What is its perimeter?$q$,2,array['Set 5']::text[],'apsmo',$q$<svg viewBox="0 0 150 150" width="150" height="150" xmlns="http://www.w3.org/2000/svg" font-family="Georgia,serif" font-size="13"><rect x="20" y="54" width="34" height="34" fill="#fff" stroke="#1f2130" stroke-width="1.8"/><rect x="54" y="54" width="34" height="34" fill="#fff" stroke="#1f2130" stroke-width="1.8"/><rect x="88" y="54" width="34" height="34" fill="#fff" stroke="#1f2130" stroke-width="1.8"/><rect x="88" y="20" width="34" height="34" fill="#fff" stroke="#1f2130" stroke-width="1.8"/><rect x="20" y="88" width="34" height="34" fill="#fff" stroke="#1f2130" stroke-width="1.8"/><rect x="54" y="54" width="34" height="34" fill="#fff" stroke="#1f2130" stroke-width="1.8"/></svg>$q$,'S5-1D'),
  (145,5,$q$A broken seat is in the 3rd row from the front and the 18th row from the back. It has 12 seats to its left and 17 to its right. Every row has the same number of seats. How many seats are there?$q$,3,array['Set 5']::text[],'apsmo',null,'S5-1E'),
  (145,6,$q$Kristen says: "Multiply my cat's age by 4, then divide by 12, and you get 5." How old is the cat?$q$,1,array['Set 5']::text[],'apsmo',null,'S5-2A'),
  (145,7,$q$Amy's toy sticks are 5 cm, 10 cm, 25 cm, 50 cm and 1 m long. After she lost one, the total length of the rest was exactly seven times the length her brother had. Which stick did she lose? (Book wording compressed in the scan.)$q$,1,array['Set 5']::text[],'apsmo',null,'S5-2B'),
  (145,8,$q$In a four-digit number: thousands + hundreds = 3; the tens digit is 4 times the hundreds digit; the ones digit is 7 more than the thousands digit; no two digits are equal. What is the number?$q$,2,array['Set 5']::text[],'apsmo',null,'S5-2C'),
  (145,9,$q$A square sheet of paper is folded in half to make a rectangle with perimeter 24 cm. What was the area of the square?$q$,2,array['Set 5']::text[],'apsmo',null,'S5-2D'),
  (145,10,$q$Sydney is 295 km from Gulgong. Cyclist A leaves Sydney at 1:00 p.m. riding at 50 km/h toward Gulgong. Cyclist B leaves Gulgong at 1:30 p.m. riding at 40 km/h toward Sydney. When do they pass each other?$q$,3,array['Set 5']::text[],'apsmo',null,'S5-2E'),
  (145,11,$q$For every two widgets bought at the regular price, a third costs only $4. I bought nine widgets for $90. What is the regular price?$q$,1,array['Set 5']::text[],'apsmo',null,'S5-3A'),
  (145,12,$q$On his birthday Newton was 14 and his father 41 — the same digits reversed. How many years later will their ages next be reversed?$q$,1,array['Set 5']::text[],'apsmo',null,'S5-3B'),
  (145,13,$q$A clock is set correctly at 1:00 p.m. and loses 3 minutes every hour. What does it show when the true time is 10:00 a.m. the next day?$q$,2,array['Set 5']::text[],'apsmo',null,'S5-3C'),
  (145,14,$q$A square has sides of 6 cm. A rectangle 3 cm wide has the same area. What is the rectangle's perimeter?$q$,2,array['Set 5']::text[],'apsmo',null,'S5-3D'),
  (145,15,$q$A set of different counting numbers adds to 350 and has average 50. One of the numbers is 100. What is the greatest number that can be in the set?$q$,3,array['Set 5']::text[],'apsmo',null,'S5-3E'),
  (145,16,$q$A 14-digit credit card number fills 14 boxes. Box 1 is A, box 3 is 7, box 12 is 7 and box 14 is 4. Any three digits in a row add to 20. What digit is A?$q$,1,array['Set 5']::text[],'apsmo',$q$<svg viewBox="0 0 356 60" width="356" height="60" xmlns="http://www.w3.org/2000/svg" font-family="Georgia,serif" font-size="13"><rect x="10" y="15" width="24" height="30" fill="#fff" stroke="#1f2130" stroke-width="1.5"/><text x="22" y="36" text-anchor="middle" font-size="15" font-weight="bold" font-style="italic">A</text><rect x="34" y="15" width="24" height="30" fill="#fff" stroke="#1f2130" stroke-width="1.5"/><rect x="58" y="15" width="24" height="30" fill="#fff" stroke="#1f2130" stroke-width="1.5"/><text x="70" y="36" text-anchor="middle" font-size="15" font-weight="bold">7</text><rect x="82" y="15" width="24" height="30" fill="#fff" stroke="#1f2130" stroke-width="1.5"/><rect x="106" y="15" width="24" height="30" fill="#fff" stroke="#1f2130" stroke-width="1.5"/><rect x="130" y="15" width="24" height="30" fill="#fff" stroke="#1f2130" stroke-width="1.5"/><rect x="154" y="15" width="24" height="30" fill="#fff" stroke="#1f2130" stroke-width="1.5"/><rect x="178" y="15" width="24" height="30" fill="#fff" stroke="#1f2130" stroke-width="1.5"/><rect x="202" y="15" width="24" height="30" fill="#fff" stroke="#1f2130" stroke-width="1.5"/><rect x="226" y="15" width="24" height="30" fill="#fff" stroke="#1f2130" stroke-width="1.5"/><rect x="250" y="15" width="24" height="30" fill="#fff" stroke="#1f2130" stroke-width="1.5"/><rect x="274" y="15" width="24" height="30" fill="#fff" stroke="#1f2130" stroke-width="1.5"/><text x="286" y="36" text-anchor="middle" font-size="15" font-weight="bold">7</text><rect x="298" y="15" width="24" height="30" fill="#fff" stroke="#1f2130" stroke-width="1.5"/><rect x="322" y="15" width="24" height="30" fill="#fff" stroke="#1f2130" stroke-width="1.5"/><text x="334" y="36" text-anchor="middle" font-size="15" font-weight="bold">4</text></svg>$q$,'S5-4A'),
  (145,17,$q$A grocer bought 15 dozen oranges at $1.00 a dozen, threw away 20 rotten ones and sold the rest at 8 for 85 cents. What was her profit?$q$,2,array['Set 5']::text[],'apsmo',null,'S5-4B'),
