  (145,19,$q$In A8 × 3B = 2730, different letters are different digits. Find A and B.$q$,3,array['Set 5']::text[],'apsmo',$q$<svg viewBox="0 0 170 164" width="170" height="164" xmlns="http://www.w3.org/2000/svg" font-family="Georgia,serif" font-size="13"><text x="140" y="30" text-anchor="end" font-size="20" font-style="italic">A 8</text><text x="140" y="58" text-anchor="end" font-size="20" font-style="italic">× 3 B</text><line x1="70" y1="66" x2="145" y2="66" stroke="#1f2130" stroke-width="1.8"/><text x="140" y="92" text-anchor="end" font-size="20" >_ _ _</text><text x="140" y="118" text-anchor="end" font-size="20" >_ _ _</text><line x1="70" y1="126" x2="145" y2="126" stroke="#1f2130" stroke-width="1.8"/><text x="140" y="152" text-anchor="end" font-size="20" >2 7 3 0</text></svg>$q$,'S5-4D'),
  (145,20,$q$A firefighter on the middle rung of a ladder climbs up 3, goes down 5, climbs up 7, and then climbs the last 6 rungs to the top. How many rungs does the ladder have?$q$,3,array['Set 5']::text[],'apsmo',null,'S5-4E'),
  (145,21,$q$Twins Joanie and Tony start with the same money. Joanie buys 1 chocolate bar and has 70c left; Tony buys 3 bars and has 20c left. How much did Joanie start with?$q$,1,array['Set 5']::text[],'apsmo',null,'S5-5A'),
  (145,22,$q$In one day a man binds 100 books and his helper binds a quarter as many. They take turns working full days. How many days to bind 500 books?$q$,1,array['Set 5']::text[],'apsmo',null,'S5-5B'),
  (145,23,$q$What is the greatest possible value of BAD + MAD + DAM if different letters are different digits chosen from 1, 3, 8 and 9?$q$,3,array['Set 5']::text[],'apsmo',null,'S5-5C'),
  (145,24,$q$A one-storey mansion is built on a block 70 m wide (street side) and 100 m deep. It must be 30 m back from the street, 20 m from the back fence, and 10 m from each side fence. What is the greatest area it can have?$q$,3,array['Set 5']::text[],'apsmo',$q$<svg viewBox="0 0 240 250" width="240" height="250" xmlns="http://www.w3.org/2000/svg" font-family="Georgia,serif" font-size="13"><rect x="30" y="20" width="140" height="200" fill="#eef6e8" stroke="#1f2130" stroke-width="1.8"/><rect x="50" y="60" width="100" height="100" fill="#cfcbee" stroke="#1f2130" stroke-width="1.8"/><text x="100" y="114" text-anchor="middle" font-size="12" font-style="italic">mansion</text><text x="100" y="238" text-anchor="middle" font-size="12" >street (70 m)</text><text x="100" y="194" text-anchor="middle" font-size="11" >30 m</text><text x="100" y="44" text-anchor="middle" font-size="11" >20 m</text><text x="40" y="114" text-anchor="middle" font-size="11" >10</text><text x="160" y="114" text-anchor="middle" font-size="11" >10</text><text x="188" y="120" text-anchor="start" font-size="11" >100 m</text></svg>$q$,'S5-5D'),
  (145,25,$q$At Hudson High the first class starts at 8:26 a.m. and the fourth class ends at 11:26 a.m. There are 4 minutes between classes and every class is the same length. How long is a class?$q$,2,array['Set 5']::text[],'apsmo',null,'S5-5E'),
  (146,1,$q$Find the value of 268 + 1375 + 6179 − 168 − 1275 − 6079.$q$,1,array['Set 6']::text[],'apsmo',null,'S6-1A'),
  (146,2,$q$Eight boxes each hold at least one marble. All boxes hold different numbers except two that hold the same. What is the fewest marbles in total?$q$,2,array['Set 6']::text[],'apsmo',null,'S6-1B'),
  (146,3,$q$Find the whole number less than 100 that is a multiple of 3, a multiple of 5, odd, and has an odd digit sum.$q$,2,array['Set 6']::text[],'apsmo',null,'S6-1C'),
  (146,4,$q$Takeru has four 1 cm blocks, three 5 cm blocks and three 25 cm blocks. Joining blocks end to end, how many different lengths of at least 1 cm can he make?$q$,3,array['Set 6']::text[],'apsmo',null,'S6-1D'),
  (146,5,$q$A plus-shaped figure is made of five congruent squares. Its perimeter is 72 cm. What is its area?$q$,3,array['Set 6']::text[],'apsmo',$q$<svg viewBox="0 0 145 145" width="145" height="145" xmlns="http://www.w3.org/2000/svg" font-family="Georgia,serif" font-size="13"><rect x="54" y="20" width="34" height="34" fill="#fff" stroke="#1f2130" stroke-width="1.8" stroke-dasharray=""/><rect x="20" y="54" width="34" height="34" fill="#fff" stroke="#1f2130" stroke-width="1.8" stroke-dasharray=""/><rect x="54" y="54" width="34" height="34" fill="#fff" stroke="#1f2130" stroke-width="1.8" stroke-dasharray=""/><rect x="88" y="54" width="34" height="34" fill="#fff" stroke="#1f2130" stroke-width="1.8" stroke-dasharray=""/><rect x="54" y="88" width="34" height="34" fill="#fff" stroke="#1f2130" stroke-width="1.8" stroke-dasharray=""/></svg>$q$,'S6-1E')
insert into problems (chapter, idx, prompt, difficulty, technique_tags, source, diagram_svg, source_ref) values
  (146,6,$q$An odd number between 301 and 370 has three different digits, and its digit sum is five times its hundreds digit. Find the number.$q$,1,array['Set 6']::text[],'apsmo',null,'S6-2A'),
  (146,7,$q$In the subtraction PR5T − 47Y6 = 1998, both are four-digit numbers. What number is PR5T?$q$,1,array['Set 6']::text[],'apsmo',null,'S6-2B'),
  (146,8,$q$Ten people stand in a line. The first goes to the back and the next sits down. This repeats until one person is left. What was that person's original position?$q$,3,array['Set 6']::text[],'apsmo',null,'S6-2C'),
  (146,9,$q$Tape 2 cm wide is used to cover a cube with 10 cm edges completely with no overlap. How long is the tape?$q$,3,array['Set 6']::text[],'apsmo',null,'S6-2D'),
  (146,10,$q$Five club members share the cost of a used computer equally. Later three new members join and pay their fair share, which saves each original member $15. What was the price?$q$,3,array['Set 6']::text[],'apsmo',null,'S6-2E'),
  (146,11,$q$Dr Bolton's birth year: the tens digit is twice the thousands digit, the ones digit is three times the tens digit, and the hundreds digit is the sum of the other three. When was he born?$q$,1,array['Set 6']::text[],'apsmo',null,'S6-3A'),
