  (146,13,$q$Numbers like 543 or 531 have digits in decreasing order (each digit smaller than the one to its left). How many whole numbers between 100 and 599 have this property?$q$,3,array['Set 6']::text[],'apsmo',null,'S6-3C'),
  (146,14,$q$One light flashes every 2 minutes and another every 7 minutes. Both flash at 1 p.m. When is the first time after 3 p.m. that they flash together?$q$,2,array['Set 6']::text[],'apsmo',null,'S6-3D'),
  (146,15,$q$Richard has 17 weights totalling 76 g; each is 5 g, 10 g or 1 g. He has twice as many 1 g weights as 10 g weights. How many 5 g weights?$q$,3,array['Set 6']::text[],'apsmo',null,'S6-3E'),
  (146,16,$q$A dial has the numbers 1 to 7 equally spaced. The hand points to 5 and moves clockwise to the next number every hour. Where does it point 24 hours from now?$q$,1,array['Set 6']::text[],'apsmo',$q$<svg viewBox="0 0 180 180" width="180" height="180" xmlns="http://www.w3.org/2000/svg" font-family="Georgia,serif" font-size="13"><circle cx="90" cy="90" r="70" fill="#fff" stroke="#1f2130" stroke-width="1.8"/><text x="90.0" y="39.0" text-anchor="middle" font-size="15" font-weight="bold">7</text><text x="133.78256301820966" y="60.084571095910924" text-anchor="middle" font-size="15" font-weight="bold">1</text><text x="144.59596308218212" y="107.4611723015536" text-anchor="middle" font-size="15" font-weight="bold">2</text><text x="114.29748939058325" y="145.45425660253548" text-anchor="middle" font-size="15" font-weight="bold">3</text><text x="65.70251060941675" y="145.45425660253548" text-anchor="middle" font-size="15" font-weight="bold">4</text><text x="35.404036917817876" y="107.46117230155362" text-anchor="middle" font-size="15" font-weight="bold">5</text><text x="46.21743698179033" y="60.08457109591093" text-anchor="middle" font-size="15" font-weight="bold">6</text><line x1="90" y1="90" x2="51.0" y2="98.9" stroke="#5b4fcf" stroke-width="3" stroke-linecap="round"/><circle cx="90" cy="90" r="4" fill="#5b4fcf"/></svg>$q$,'S6-4A'),
  (146,17,$q$A square contains squares A (16 m²) and B (9 m²) side by side along its bottom edge. What is the perimeter of the shaded region (the rest of the big square)?$q$,3,array['Set 6']::text[],'apsmo',$q$<svg viewBox="0 0 195 195" width="195" height="195" xmlns="http://www.w3.org/2000/svg" font-family="Georgia,serif" font-size="13"><rect x="20" y="20" width="154" height="154" fill="#cfcbee" stroke="#1f2130" stroke-width="1.8"/><rect x="20" y="86" width="88" height="88" fill="#fff" stroke="#1f2130" stroke-width="1.8"/><text x="64" y="136" text-anchor="middle" font-size="16" font-style="italic">A</text><rect x="108" y="108" width="66" height="66" fill="#fff" stroke="#1f2130" stroke-width="1.8"/><text x="141.0" y="147.0" text-anchor="middle" font-size="16" font-style="italic">B</text></svg>$q$,'S6-4B'),
  (146,18,$q$The average of six numbers is 4. A seventh number is added and the average becomes 5. What is the seventh number?$q$,2,array['Set 6']::text[],'apsmo',null,'S6-4C'),
  (146,19,$q$Place 1, 2, 3, 4 in the 4 × 4 grid so each appears once in every row, column and both diagonals. Row 1 is 1 2 3 4; row 3 starts with 4 and ends with 1. Find A and B, the first two squares of row 4.$q$,3,array['Set 6']::text[],'apsmo',$q$<svg viewBox="0 0 190 190" width="190" height="190" xmlns="http://www.w3.org/2000/svg" font-family="Georgia,serif" font-size="13"><line x1="15" y1="15" x2="15" y2="175" stroke="#1f2130" stroke-width="1"/><line x1="55" y1="15" x2="55" y2="175" stroke="#1f2130" stroke-width="1"/><line x1="95" y1="15" x2="95" y2="175" stroke="#1f2130" stroke-width="1"/><line x1="135" y1="15" x2="135" y2="175" stroke="#1f2130" stroke-width="1"/><line x1="175" y1="15" x2="175" y2="175" stroke="#1f2130" stroke-width="1"/><line x1="15" y1="15" x2="175" y2="15" stroke="#1f2130" stroke-width="1"/><line x1="15" y1="55" x2="175" y2="55" stroke="#1f2130" stroke-width="1"/><line x1="15" y1="95" x2="175" y2="95" stroke="#1f2130" stroke-width="1"/><line x1="15" y1="135" x2="175" y2="135" stroke="#1f2130" stroke-width="1"/><line x1="15" y1="175" x2="175" y2="175" stroke="#1f2130" stroke-width="1"/><text x="35.0" y="41.0" text-anchor="middle" font-size="17" font-weight="bold">1</text><text x="75.0" y="41.0" text-anchor="middle" font-size="17" font-weight="bold">2</text><text x="115.0" y="41.0" text-anchor="middle" font-size="17" font-weight="bold">3</text><text x="155.0" y="41.0" text-anchor="middle" font-size="17" font-weight="bold">4</text><text x="35.0" y="121.0" text-anchor="middle" font-size="17" font-weight="bold">4</text><text x="155.0" y="121.0" text-anchor="middle" font-size="17" font-weight="bold">1</text><text x="35.0" y="161.0" text-anchor="middle" font-size="17" font-weight="bold" font-style="italic">A</text><text x="75.0" y="161.0" text-anchor="middle" font-size="17" font-weight="bold" font-style="italic">B</text></svg>$q$,'S6-4D'),
  (146,20,$q$Morning: Sandy takes out half the coins in her bank; evening: puts in 20. Next morning: takes out a third; evening: puts in 4. Next morning: takes out half, leaving 15. How many coins were in the bank at first?$q$,3,array['Set 6']::text[],'apsmo',null,'S6-4E'),
  (146,21,$q$Bob adds 4 stamps to his collection every day. At the end of three days he has 50. How many at the end of 10 days?$q$,1,array['Set 6']::text[],'apsmo',null,'S6-5A'),
  (146,22,$q$Mr Jackson's odometer shows 62 222 km. What is the least distance he must drive before it again shows 4 of its 5 digits the same?$q$,2,array['Set 6']::text[],'apsmo',null,'S6-5B'),
  (146,23,$q$Three circles A, B, C overlap like a Venn diagram. The parts only in A, only in B and only in C hold 6, 4 and 1. Put 2, 3, 5 and 7 in the four empty regions (one each) so every circle has the same total. What is that total?$q$,3,array['Set 6']::text[],'apsmo',$q$<svg viewBox="0 0 220 205" width="220" height="205" xmlns="http://www.w3.org/2000/svg" font-family="Georgia,serif" font-size="13"><circle cx="80" cy="75" r="55" fill="none" stroke="#1f2130" stroke-width="1.8"/><circle cx="140" cy="75" r="55" fill="none" stroke="#1f2130" stroke-width="1.8"/><circle cx="110" cy="125" r="55" fill="none" stroke="#1f2130" stroke-width="1.8"/><text x="55" y="70" text-anchor="middle" font-size="16" font-weight="bold">6</text><text x="165" y="70" text-anchor="middle" font-size="16" font-weight="bold">4</text><text x="110" y="160" text-anchor="middle" font-size="16" font-weight="bold">1</text><text x="30" y="26" text-anchor="middle" font-size="13" font-style="italic">A</text><text x="190" y="26" text-anchor="middle" font-size="13" font-style="italic">B</text><text x="110" y="196" text-anchor="middle" font-size="13" font-style="italic">C</text></svg>$q$,'S6-5C'),
  (146,24,$q$Twenty unit cubes are glued into a 3 × 3 × 3 shape with see-through holes: the centre cube and the six face-centre cubes are missing. If it is dipped in paint, how many square units are painted?$q$,3,array['Set 6']::text[],'apsmo',$q$<svg viewBox="0 0 161 184" width="161" height="184" xmlns="http://www.w3.org/2000/svg" font-family="Georgia,serif" font-size="13"><polygon points="80.7,92.0 105.0,78.0 105.0,50.0 80.7,64.0" fill="#e4e1f6" stroke="#1f2130" stroke-width="1"/><polygon points="80.7,92.0 56.5,78.0 56.5,50.0 80.7,64.0" fill="#c9c4ec" stroke="#1f2130" stroke-width="1"/><polygon points="80.7,36.0 105.0,22.0 80.7,8.0 56.5,22.0" fill="#ffffff" stroke="#1f2130" stroke-width="1"/><polygon points="56.5,106.0 80.7,92.0 56.5,78.0 32.2,92.0" fill="#ffffff" stroke="#1f2130" stroke-width="1"/><polygon points="56.5,134.0 80.7,120.0 80.7,92.0 56.5,106.0" fill="#e4e1f6" stroke="#1f2130" stroke-width="1"/><polygon points="105.0,106.0 129.2,92.0 105.0,78.0 80.7,92.0" fill="#ffffff" stroke="#1f2130" stroke-width="1"/><polygon points="105.0,134.0 80.7,120.0 80.7,92.0 105.0,106.0" fill="#c9c4ec" stroke="#1f2130" stroke-width="1"/><polygon points="56.5,50.0 80.7,36.0 56.5,22.0 32.2,36.0" fill="#ffffff" stroke="#1f2130" stroke-width="1"/><polygon points="56.5,78.0 80.7,64.0 80.7,36.0 56.5,50.0" fill="#e4e1f6" stroke="#1f2130" stroke-width="1"/><polygon points="105.0,50.0 129.2,36.0 105.0,22.0 80.7,36.0" fill="#ffffff" stroke="#1f2130" stroke-width="1"/><polygon points="105.0,78.0 80.7,64.0 80.7,36.0 105.0,50.0" fill="#c9c4ec" stroke="#1f2130" stroke-width="1"/><polygon points="32.2,148.0 8.0,134.0 8.0,106.0 32.2,120.0" fill="#c9c4ec" stroke="#1f2130" stroke-width="1"/><polygon points="129.2,148.0 153.5,134.0 153.5,106.0 129.2,120.0" fill="#e4e1f6" stroke="#1f2130" stroke-width="1"/><polygon points="32.2,120.0 56.5,106.0 56.5,78.0 32.2,92.0" fill="#e4e1f6" stroke="#1f2130" stroke-width="1"/><polygon points="32.2,120.0 8.0,106.0 8.0,78.0 32.2,92.0" fill="#c9c4ec" stroke