  (146,25,$q$The Reds beat the Blues. Their scores add to 44 and differ by 20. How many did the Reds score?$q$,2,array['Set 6']::text[],'apsmo',null,'S6-5E'),
  (147,1,$q$What is the value of 25 × 17 × 4 × 20?$q$,1,array['Set 7']::text[],'apsmo',null,'S7-1A'),
  (147,2,$q$Four people can sit at one card table. Two tables pushed end to end seat 6. How many tables pushed end to end are needed to seat 22 people?$q$,1,array['Set 7']::text[],'apsmo',$q$<svg viewBox="0 0 180 160" width="180" height="160" xmlns="http://www.w3.org/2000/svg" font-family="Georgia,serif" font-size="13"><rect x="60" y="30" width="60" height="50" rx="8" fill="#fff" stroke="#1f2130" stroke-width="1.8"/><rect x="60" y="80" width="60" height="50" rx="8" fill="#fff" stroke="#1f2130" stroke-width="1.8"/><circle cx="90" cy="18" r="9" fill="#cfcbee" stroke="#1f2130"/><circle cx="90" cy="142" r="9" fill="#cfcbee" stroke="#1f2130"/><circle cx="45" cy="55" r="9" fill="#cfcbee" stroke="#1f2130"/><circle cx="135" cy="55" r="9" fill="#cfcbee" stroke="#1f2130"/><circle cx="45" cy="105" r="9" fill="#cfcbee" stroke="#1f2130"/><circle cx="135" cy="105" r="9" fill="#cfcbee" stroke="#1f2130"/></svg>$q$,'S7-1B'),
  (147,3,$q$A group had 2 girls for every boy. Then 24 more girls joined, and now there are 5 girls for every boy. How many boys are in the group?$q$,2,array['Set 7']::text[],'apsmo',null,'S7-1C'),
  (147,4,$q$One owl hoots every 3 hours, a second every 8 hours and a third every 12 hours. All three hoot together at the start. In the next 80 hours, how many times do exactly two owls hoot together?$q$,3,array['Set 7']::text[],'apsmo',null,'S7-1D'),
  (147,5,$q$Amy, Dawn and Soumiya sit at a round table facing the centre. Their rings are red, green and blue (one each). The green ring is at Amy's right. The red ring is at Soumiya's left. What colour is each girl's ring?$q$,3,array['Set 7']::text[],'apsmo',null,'S7-1E'),
  (147,6,$q$A case holds 2 cartons; a carton 3 boxes; a box 4 bundles; a bundle 5 envelopes; an envelope 6 pencils. How many pencils can one case hold?$q$,1,array['Set 7']::text[],'apsmo',null,'S7-2A'),
  (147,7,$q$A factory has enough oil for 30 days using 4 barrels a day. How many barrels a day would make it last 40 days?$q$,2,array['Set 7']::text[],'apsmo',null,'S7-2B'),
  (147,8,$q$Find the four-digit number ABCD if ABCD × 9 = DCBA.$q$,2,array['Set 7']::text[],'apsmo',null,'S7-2C'),
  (147,9,$q$How many multiples of 7 are there between 100 and 1000?$q$,3,array['Set 7']::text[],'apsmo',null,'S7-2D'),
  (147,10,$q$A 10 m by 20 m garden is surrounded by a path 1 m wide. What is the area of the path?$q$,3,array['Set 7']::text[],'apsmo',$q$<svg viewBox="0 0 260 166" width="260" height="166" xmlns="http://www.w3.org/2000/svg" font-family="Georgia,serif" font-size="13"><rect x="20" y="20" width="220" height="120" fill="#cfcbee" stroke="#1f2130" stroke-width="1.8"/><rect x="31" y="31" width="198" height="98" fill="#eef6e8" stroke="#1f2130" stroke-width="1.8"/><text x="130" y="84" text-anchor="middle" font-size="12" >garden 10 m × 20 m</text><text x="130" y="156" text-anchor="middle" font-size="11" fill="#6b6e85">path 1 m wide (shaded)</text></svg>$q$,'S7-2E'),
  (147,11,$q$Toni multiplies a number by 3, adds 4 and divides by 2. The result is 14. What was the number?$q$,1,array['Set 7']::text[],'apsmo',null,'S7-5A'),
  (147,12,$q$Suppose that five days before the day after tomorrow was Friday. What day was yesterday?$q$,1,array['Set 7']::text[],'apsmo',null,'S7-5B'),
  (147,13,$q$If 3 smiles = 10 grins and 6 grins = 9 laughs, how many laughs equal 2 smiles?$q$,3,array['Set 7']::text[],'apsmo',null,'S7-5C'),
  (147,14,$q$Anna covers a box with a square base of area 16 cm² and volume 80 cm³ in paper, top and bottom included, with nothing left over. How much paper?$q$,3,array['Set 7']::text[],'apsmo',null,'S7-5D'),
  (147,15,$q$The digits 1, 2, 3, 4, 5 are each used once in ABCDE. ABC is divisible by 4, BCD by 5 and CDE by 3. Find ABCDE.$q$,3,array['Set 7']::text[],'apsmo',null,'S7-5E'),
  (148,1,$q$What number does N represent if 42 × 25 = 21 × N?$q$,1,array['Set 8']::text[],'apsmo',null,'S8-1A'),
  (148,2,$q$Find the number between 100 and 999 whose digits add to 12, whose hundreds digit equals the tens digit plus the ones digit, and whose hundreds digit is one more than its tens digit.$q$,2,array['Set 8']::text[],'apsmo',null,'S8-1B'),
  (148,3,$q$For every $3 Marisa spends, Andie spends $5. Andie spends $120 more than Marisa. How much does Andie spend?$q$,2,array['Set 8']::text[],'apsmo',null,'S8-1C'),
  (148,4,$q$A 4 cm by 12 cm rectangle is split into four triangles by joining a point inside to the four corners. Three triangles have areas 16, 8 and 18 cm². What is the area of the shaded triangle?$q$,1,array['Set 8']::text[],'apsmo',$q$<svg viewBox="0 0 280 120" width="280" height="120" xmlns="http://www.w3.org/2000/svg" font-family="Georgia,serif" font-size="13"><rect x="20" y="20" width="240" height="80" fill="#fff" stroke="#1f2130" stroke-width="1.8"/><polygon points="20,20 260,20 180,40" fill="#cfcbee"/><line x1="20" y1="20" x2="180" y2="40" stroke="#1f2130" stroke-width="1.5"/><line x1="260" y1="20" x2="180" y2="40" stroke="#1f2130" stroke-width="1.5"/><line x1="260" y1="100" x2="180" y2="40" stroke="#1f2130" stroke-width="1.5"/><line x1="20" y1="100" x2="180" y2="40" stroke="#1f2130" stroke-width="1.5"/><text x="70" y="66" text-anchor="middle" font-size="12" >16 cm²</text><text x="235" y="62" text-anchor="middle" font-size="12" >8 cm²</text><text x="150" y="92" text-anchor="middle" font-size="12" >18 cm²</text></svg>$q$,'S8-1D'),
  (148,5,$q$Jeff's coins can be shared equally into 9 bags or 6 bags with none left over, and into 5 bags with 2 left over. What is the smallest number he could have?$q$,3,array['Set 8']::text[],'apsmo',null,'S8-1E')
insert into problems (chapter, idx, prompt, difficulty, technique_tags, source, diagram_svg, source_ref) values
  (148,6,$q$The sum of five consecutive whole numbers is 45. What is the smallest?$q$,1,array['Set 8']::text[],'apsmo',null,'S8-2A'),
  (148,7,$q$Sara puts four books on a shelf. The blue must be somewhere left of the green, and the red somewhere left of the yellow. How many orders are possible?$q$,2,array['Set 8']::text[],'apsmo',null,'S8-2B'),
  (148,8,$q$Ann, Bill and Chris each take two vitamin C tablets a day; Wendy takes one. A bottle lasts the four of them exactly 24 days. If Wendy takes two a day instead, how long will the bottle last?$q$,2,array['Set 8']::text[],'apsmo',null,'S8-2C'),
  (148,9,$q$A rectangle's perimeter is 14 m and its sides are whole metres. List ALL possible areas.$q$,2,array['Set 8']::text[],'apsmo',null,'S8-2D'),
  (148,10,$q$Aiah lists the counting numbers from 1 to 200. How many times does the digit 4 appear?$q$,2,array['Set 8']::text[],'apsmo',null,'S8-2E'),
  (148,11,$q$A number is multiplied by 4 and then 14 is added. The result is 6 times the starting number. What is the starting number?$q$,1,array['Set 8']::text[],'apsmo',null,'S8-3A'),
  (148,12,$q$Hannah's first video game lasts 30 seconds; each later game lasts 30 seconds longer. Her final game lasts 4 minutes. Each game costs 25 cents. How much does she spend?$q$,2,array['Set 8']::text[],'apsmo',null,'S8-3B'),
  (148,13,$q$A street has 12 houses, and Dwayne's always gets more letters than any other. Today 57 letters were delivered on the street. What is the least Dwayne could have got?$q$,3,array['Set 8']::text[],'apsmo',null,'S8-3C'),
  (148,14,$q$Rectangle ACEG is divided into four smaller rectangles with whole-centimetre sides. Three areas are 6 cm² (top left), 10 cm² (top right) and 9 cm² (bottom left). What is the total area?$q$,2,array['Set 8']::text[],'apsmo',$q$<svg viewBox="0 0 240 170" width="240" height="170" xmlns="http://www.w3.org/2000/svg" font-family="Georgia,serif" font-size="13"><rect x="30" y="25" width="180" height="120" fill="#fff" stroke="#1f2130" stroke-width="2"/><line x1="90" y1="25" x2="90" y2="145" stroke="#1f2130" stroke-width="1.6"/><line x1="30" y1="65" x2="210" y2="65" stroke="#1f2130" stroke-width="1.6"/><text x="60" y="50" text-anchor="middle" font-size="12" >6 cm²</text><text x="150" y="50" text-anchor="middle" font-size="12" >10 cm²</text><text x="60" y="110" text-anchor="middle" font-size="12" >9 cm²</text><text x="22" y="20" text-anchor="middle" font-size="13" font-style="italic">A</text><text x="218" y="20" text-anchor="middle" font-size="13" font-style="italic">C</text><text x="218" y="160" text-anchor="middle" font-size="13" font-style="italic">E</text><text x="22" y="160" text-anchor="middle" font-size="13" font-style="italic">G</text></svg>$q$,'S8-3D'),
  (148,15,$q$Three darts are thrown at a board whose rings score 15, 8, 3 and 1; a miss scores 0. What is the smallest whole-number total that is impossible?$q$,3,array['Set 8']::text[],'apsmo',$q$<svg viewBox="0 0 200 200" width="200" height="200" xmlns="http://www.w3.org/2000/svg" font-family="Georgia,serif" font-size="13"><circle cx="100.0" cy="100.0" r="90" fill="#e9e7f8" stroke="#1f2130" stroke-width="1.6"/><circle cx="100.0" cy="100.0" r="68" fill="#fff" stroke="#1f2130" stroke-width="1.6"/><circle cx="100.0" cy="100.0" r="46" fill="#e9e7f8" stroke="#1f2130" stroke-width="1.6"/><circle cx="100.0" cy="100.0" r="22" fill="#fff" stroke="#1f2130" stroke-width="1.6"/><text x="100.0" y="26" text-anchor="middle" font-size="13" font-weight="bold">1</text><text x="100.0" y="48" text-anchor="middle" font-size="13" font-weight="bold">3</text><text x="100.0" y="70" text-anchor="middle" font-size="13" font-weight="bold">8</text><text x="100.0" y="105" text-anchor="middle" font-size="13" font-weight="bold">15</text></svg>$q$,'S8-3E'),
  (148,16,$q$Maddison buys some 5c and some 10c stamps for $1.00 and gets 13 stamps. How many 5c stamps does she buy?$q$,1,array['Set 8']::text[],'apsmo',null,'S8-4A'),
  (148,17,$q$How many even two-digit numbers have an odd digit sum?$q$,2,array['Set 8']::text[],'apsmo',null,'S8-4B'),
  (148,18,$q$Counting by 4s from 3 to 99 gives 3, 7, 11, …, 99. If 99 is the Nth number, what is N?$q$,3,array['Set 8']::text[],'apsmo',null,'S8-4C'),
  (148,19,$q$Thirty 1 cm cubes are joined face to face in a straight line. What is the surface area of the solid?$q$,2,array['Set 8']::text[],'apsmo',$q$<svg viewBox="0 0 187 137" width="187" height="137" xmlns="http://www.w3.org/2000/svg" font-family="Georgia,serif" font-size="13"><polygon points="160.4,30.0 179.5,19.0 160.4,8.0 141.4,19.0" fill="#ffffff" stroke="#1f2130" stroke-width="1"/><polygon points="160.4,52.0 179.5,41.0 179.5,19.0 160.4,30.0" fill="#e4e1f6" stroke="#1f2130" stroke-width="1"/><polygon points="141.4,41.0 160.4,30.0 141.4,19.0 122.3,30.0" fill="#ffffff" stroke="#1f2130" stroke-width="1"/><polygon points="141.4,63.0 160.4,52.0 160.4,30.0 141.4,41.0" fill="#e4e1f6" stroke="#1f2130" stroke-width="1"/><polygon points="122.3,52.0 141.4,41.0 122.3,30.0 103.3,41.0" fill="#ffffff" stroke="#1f2130" stroke-width="1"/><polygon points="122.3,74.0 141.4,63.0 141.4,41.0 122.3,52.0" fill="#e4e1f6" stroke="#1f2130" stroke-width="1"/><polygon points="103.3,63.0 122.3,52.0 103.3,41.0 84.2,52.0" fill="#ffffff" stroke="#1f2130" stroke-width="1"/><polygon points="103.3,85.0 122.3,74.0 122.3,52.0 103.3,63.0" fill="#e4e1f6" stroke="#1f2130" stroke-width="1"/><polygon points="84.2,74.0 103.3,63.0 84.2,52.0 65.2,63.0" fill="#ffffff" stroke="#1f2130" stroke-width="1"/><polygon points="84.2,96.0 103.3,85.0 103.3,63.0 84.2,74.0" fill="#e4e1f6" stroke="#1f2130" stroke-width="1"/><polygon points="65.2,85.0 84.2,74.0 65.2,63.0 46.1,74.0" fill="#ffffff" stroke="#1f2130" stroke-width="1"/><polygon points="65.2,107.0 84.2,96.0 84.2,74.0 65.2,85.0" fill="#e4e1f6" stroke="#1f2130" stroke-width="1"/><polygon points="46.1,96.0 65.2,85.0 46.1,74.0 27.1,85.0" fill="#ffffff" stroke="#1f2130" stroke-width="1"/><polygon points="46.1,118.0 65.2,107.0 65.2,85.0 46.1,96.0" fill="#e4e1f6" stroke="#1f2130" stroke-width="1"/><polygon points="27.1,107.0 46.1,96.0 27.1,85.0 8.0,96.0" fill="#ffffff" stroke="#1f2130" stroke-width="1"/><polygon points="27.1,129.0 46.1,118.0 46.1,96.0 27.1,107.0" fill="#e4e1f6" stroke="#1f2130" stroke-width="1"/><polygon points="27.1,129.0 8.0,118.0 8.0,96.0 27.1,107.0" fill="#c9c4ec" stroke="#1f2130" stroke-width="1"/></svg>$q$,'S8-4D'),
  (148,20,$q$How many different counting numbers leave a remainder of 5 when divided into 47?$q$,2,array['Set 8']::text[],'apsmo',null,'S8-4E'),
  (148,21,$q$Kristen puts boots on her four cats: front boots have 4 eyelets, rear boots 6. Each cat loses a different boot (front-left, front-right, rear-left, rear-right). How many eyelets are in the boots that remain?$q$,1,array['Set 8']::text[],'apsmo',null,'S8-5A'),
  (148,22,$q$Two years ago my age was a multiple of 6. Last year it was a multiple of 5. I am under 50. How old am I?$q$,2,array['Set 8']::text[],'apsmo',null,'S8-5B'),
  (148,23,$q$Kevin starts at town A and visits each of the other four towns exactly once. In how many orders can he do this?$q$,3,array['Set 8']::text[],'apsmo',null,'S8-5C'),
  (148,24,$q$An empty carton (with a top and a bottom) is opened and flattened into the cross-shaped figure: a 9 cm wide strip with two 7 cm flaps, and a section marked 10 cm. What is the total area of the figure?$q$,3,array['Set 8']::text[],'apsmo',$q$<svg viewBox="0 0 330 210" width="330" height="210" xmlns="http://www.w3.org/2000/svg" font-family="Georgia,serif" font-size="13"><rect x="90" y="15" width="81" height="180" fill="#fff" stroke="#1f2130" stroke-width="1.8"/><line x1="90" y1="78" x2="171" y2="78" stroke="#1f2130" stroke-dasharray="5 4"/><line x1="90" y1="105" x2="171" y2="105" stroke="#1f2130" stroke-dasharray="5 4"/><line x1="90" y1="168" x2="171" y2="168" stroke="#1f2130" stroke-dasharray="5 4"/><rect x="27" y="78" width="63" height="27" fill="#fff" stroke="#1f2130" stroke-width="1.8"/><rect x="171" y="78" width="63" height="27" fill="#fff" stroke="#1f2130" stroke-width="1.8"/><text x="130.5" y="12" text-anchor="middle" font-size="12" >9 cm</text><text x="58.5" y="73" text-anchor="middle" font-size="12" >7 cm</text><path d="M177,105 q8,0 8,45 q0,45 -8,45" fill="none" stroke="#1f2130"/><text x="193" y="155" text-anchor="start" font-size="12" >10 cm</text></svg>$q$,'S8-5D'),
  (148,25,$q$5A4 and 6B9 are three-digit numbers, 6B9 = 5A4 + 125, and 6B9 is divisible by 9. Find A.$q$,2,array['Set 8']::text[],'apsmo',null,'S8-5E'),
  (149,1,$q$Kim is the 25th person from the front of a line and the 12th from the rear. How many people are in the line?$q$,1,array['Set 9']::text[],'apsmo',null,'S9-1A'),
  (149,2,$q$There are 5 girls in a tennis class. How many different doubles teams of 2 can be formed?$q$,2,array['Set 9']::text[],'apsmo',null,'S9-1B'),
  (149,3,$q$An apple and a pear cost 25c, a pear and a banana 19c, and an apple and a banana 16c. Alex buys one of each. What does she spend?$q$,2,array['Set 9']::text[],'apsmo',null,'S9-1C'),
  (149,4,$q$A rectangle has a perimeter of 90 cm and its length is 25 cm more than its width. What is its area?$q$,3,array['Set 9']::text[],'apsmo',null,'S9-1D'),
  (149,5,$q$Find the sum of the digits of the first 25 odd counting numbers.$q$,3,array['Set 9']::text[],'apsmo',null,'S9-1E'),
  (149,6,$q$A picture 3 m across hangs in the centre of a wall 25 m long. How far is the left edge of the picture from the left end of the wall?$q$,1,array['Set 9']::text[],'apsmo',$q$<svg viewBox="0 0 280 115" width="280" height="115" xmlns="http://www.w3.org/2000/svg" font-family="Georgia,serif" font-size="13"><rect x="15" y="20" width="250" height="70" fill="#fff" stroke="#1f2130" stroke-width="1.8"/><rect x="125" y="35" width="30" height="24" fill="#cfcbee" stroke="#1f2130" stroke-width="1.5"/><line x1="140" y1="35" x2="128" y2="26" stroke="#1f2130"/><line x1="140" y1="35" x2="152" y2="26" stroke="#1f2130"/><text x="140" y="74" text-anchor="middle" font-size="11" >← 3 →</text><line x1="20" y1="82" x2="260" y2="82" stroke="#5b4fcf" stroke-width="1.2"/><text x="140" y="105" text-anchor="middle" font-size="12" >25 m wall</text></svg>$q$,'S9-2A'),
  (149,7,$q$David sells a toy car to Jessica and loses $3. Jessica sells it to Bryan for $25 and makes $6 profit. What did David pay?$q$,1,array['Set 9']::text[],'apsmo',null,'S9-2B'),
  (149,8,$q$Ashley is twice as old as Carlos. Billy is 5 years younger than Ashley. Their ages add to 25. How old is Carlos?$q$,2,array['Set 9']::text[],'apsmo',null,'S9-2C'),
  (149,9,$q$The numbers from 100 down to 0 are written in columns P, Q, R, S, T in a zigzag: 100 Q, 99 R, 98 S, 97 T, 96 S, 95 R, 94 Q, 93 P, 92 Q … Which column holds 25?$q$,3,array['Set 9']::text[],'apsmo',$q$<svg viewBox="0 0 240 200" width="240" height="200" xmlns="http://www.w3.org/2000/svg" font-family="Georgia,serif" font-size="13"><rect x="20" y="10" width="40" height="22" fill="#e9e7f8" stroke="#1f2130"/><text x="40" y="26" text-anchor="middle" font-size="13" font-weight="bold">P</text><rect x="60" y="10" width="40" height="22" fill="#e9e7f8" stroke="#1f2130"/><text x="80" y="26" text-anchor="middle" font-size="13" font-weight="bold">Q</text><rect x="100" y="10" width="40" height="22" fill="#e9e7f8" stroke="#1f2130"/><text x="120" y="26" text-anchor="middle" font-size="13" font-weight="bold">R</text><rect x="140" y="10" width="40" height="22" fill="#e9e7f8" stroke="#1f2130"/><text x="160" y="26" text-anchor="middle" font-size="13" font-weight="bold">S</text><rect x="180" y="10" width="40" height="22" fill="#e9e7f8" stroke="#1f2130"/><text x="200" y="26" text-anchor="middle" font-size="13" font-weight="bold">T</text><text x="80" y="50" text-anchor="middle" font-size="13" >100</text><text x="120" y="50" text-anchor="middle" font-size="13" >99</text><text x="160" y="50" text-anchor="middle" font-size="13" >98</text><text x="200" y="50" text-anchor="middle" font-size="13" >97</text><text x="160" y="72" text-anchor="middle" font-size="13" >96</text><text x="120" y="72" text-anchor="middle" font-size="13" >95</text><text x="80" y="72" text-anchor="middle" font-size="13" >94</text><text x="40" y="72" text-anchor="middle" font-size="13" >93</text><text x="80" y="94" text-anchor="middle" font-size="13" >92</text><text x="120" y="94" text-anchor="middle" font-size="13" >91</text><text x="160" y="94" text-anchor="middle" font-size="13" >90</text><text x="200" y="94" text-anchor="middle" font-size="13" >89</text><text x="160" y="116" text-anchor="middle" font-size="13" >88</text><text x="120" y="116" text-anchor="middle" font-size="13" >87</text><text x="80" y="116" text-anchor="middle" font-size="13" >86</text><text x="40" y="116" text-anchor="middle" font-size="13" >85</text><text x="80" y="138" text-anchor="middle" font-size="13" >84</text><text x="120" y="138" text-anchor="middle" font-size="13" >83</text><text x="160" y="138" text-anchor="middle" font-size="13" >82</text><text x="200" y="138" text-anchor="middle" font-size="13" >81</text><text x="160" y="160" text-anchor="middle" font-size="13" >80</text><text x="120" y="160" text-anchor="middle" font-size="13" >79</text><text x="80" y="160" text-anchor="middle" font-size="13" >78</text><text x="40" y="160" text-anchor="middle" font-size="13" >77</text><rect x="20" y="32" width="200" height="138" fill="none" stroke="#1f2130"/><line x1="60" y1="10" x2="60" y2="170" stroke="#1f2130" stroke-width=".8"/><line x1="100" y1="10" x2="100" y2="170" stroke="#1f2130" stroke-width=".8"/><line x1="140" y1="10" x2="140" y2="170" stroke="#1f2130" stroke-width=".8"/><line x1="180" y1="10" x2="180" y2="170" stroke="#1f2130" stroke-width=".8"/><text x="220" y="188" text-anchor="end" font-size="11" font-style="italic">… and so on</text></svg>$q$,'S9-2D'),
  (149,10,$q$A cubical box with no top is 4 cm on each edge and is exactly filled with 64 one-centimetre cubes. How many cubes touch the box?$q$,3,array['Set 9']::text[],'apsmo',null,'S9-2E'),
  (149,11,$q$T-shirts cost $8. Amy buys 1, Becky 3, Colin 5, Dan 7, and Emily as many as Amy, Becky and Colin together. How much do the five spend?$q$,1,array['Set 9']::text[],'apsmo',null,'S9-3A'),
  (149,12,$q$Find the sum of all counting numbers less than 25 that are not divisible by 2 or 5.$q$,2,array['Set 9']::text[],'apsmo',null,'S9-3B'),
  (149,13,$q$Of 25 girls, 8 joined athletics, 13 joined maths and 6 joined both. How many joined neither?$q$,2,array['Set 9']::text[],'apsmo',null,'S9-3C'),
  (149,14,$q$I climb half the steps of a staircase, then one-third of the remaining steps, then one-eighth of the rest, and stop. What is the smallest possible number of steps?$q$,3,array['Set 9']::text[],'apsmo',null,'S9-3D'),
  (149,15,$q$ABCD (15 cm by 8 cm) and EBCF are rectangles; AE = 12 cm. Find the total area of the shaded regions (triangle ADF and rectangle EBCF).$q$,3,array['Set 9']::text[],'apsmo',$q$<svg viewBox="0 0 300 180" width="300" height="180" xmlns="http://www.w3.org/2000/svg" font-family="Georgia,serif" font-size="13"><rect x="30" y="25" width="210" height="112" fill="#fff" stroke="#1f2130" stroke-width="1.8"/><polygon points="30,25 30,137 198,137" fill="#cfcbee" stroke="#1f2130" stroke-width="1.5"/><rect x="198" y="25" width="42" height="112" fill="#cfcbee" stroke="#1f2130" stroke-width="1.5"/><text x="22" y="19" text-anchor="middle" font-size="13" font-style="italic">A</text><text x="198" y="19" text-anchor="middle" font-size="13" font-style="italic">E</text><text x="248" y="19" text-anchor="middle" font-size="13" font-style="italic">B</text><text x="22" y="153" text-anchor="middle" font-size="13" font-style="italic">D</text><text x="198" y="153" text-anchor="middle" font-size="13" font-style="italic">F</text><text x="248" y="153" text-anchor="middle" font-size="13" font-style="italic">C</text><text x="114" y="39" text-anchor="middle" font-size="12" >12 cm</text><text x="262" y="85" text-anchor="start" font-size="12" >8 cm</text><text x="135.0" y="171" text-anchor="middle" font-size="12" >← 15 cm →</text></svg>$q$,'S9-3E'),
  (149,16,$q$Six piles each have a different number of counters, with at least one in each. What is the least possible total?$q$,1,array['Set 9']::text[],'apsmo',null,'S9-4A'),
  (149,17,$q$The ages of Amanda, Brittany and Carly are all prime numbers. Amanda is the youngest, and Amanda's age plus Brittany's equals Carly's. How old is Amanda?$q$,1,array['Set 9']::text[],'apsmo',null,'S9-4B'),
  (149,18,$q$A bus holds 24 adults or 30 children. 25 children are already on it. What is the most adults that can still get on?$q$,2,array['Set 9']::text[],'apsmo',null,'S9-4C'),
  (149,19,$q$ABCD is a square and DEFG a rectangle with EF = 25 cm. D is the midpoint of CE. The perimeter of the whole shaded figure is 180 cm. Find AG.$q$,3,array['Set 9']::text[],'apsmo',$q$<svg viewBox="0 0 330 175" width="330" height="175" xmlns="http://www.w3.org/2000/svg" font-family="Georgia,serif" font-size="13"><rect x="30" y="25" width="120" height="120" fill="#cfcbee" stroke="#1f2130" stroke-width="1.8"/><rect x="150" y="45" width="120" height="100" fill="#cfcbee" stroke="#1f2130" stroke-width="1.8"/><text x="20" y="21" text-anchor="middle" font-size="13" font-style="italic">B</text><text x="150" y="19" text-anchor="middle" font-size="13" font-style="italic">A</text><text x="160" y="59" text-anchor="middle" font-size="13" font-style="italic">G</text><text x="278" y="41" text-anchor="middle" font-size="13" font-style="italic">F</text><text x="20" y="161" text-anchor="middle" font-size="13" font-style="italic">C</text><text x="150" y="163" text-anchor="middle" font-size="13" font-style="italic">D</text><text x="278" y="161" text-anchor="middle" font-size="13" font-style="italic">E</text><text x="284" y="98" text-anchor="start" font-size="12" >25 cm</text></svg>$q$,'S9-4D'),
  (149,20,$q$The average of 20 numbers is 20; the average of 60 other numbers is 60. What is the average of all 80?$q$,3,array['Set 9']::text[],'apsmo',null,'S9-4E')
insert into problem_answers (chapter, idx, answer, method, answer_key, mark_mode, solved_by, verified) values
  (141,1,$q$2:45 — 100 hours = 4 full days (96 h) + 4 hours. Days don't change a 12-hour clock, so just add 4 hours.$q$,$q$100 hours = 4 full days (96 h) + 4 hours. Days don't change a 12-hour clock, so just add 4 hours.$q$,$q$2:45$q$,'auto','school',true),
  (141,2,$q$20 cubes — Count layer by layer from the top: 1, then 1+2 = 3, then 1+2+3 = 6, then 1+2+3+4 = 10 (triangular numbers).$q$,$q$Count layer by layer from the top: 1, then 1+2 = 3, then 1+2+3 = 6, then 1+2+3+4 = 10 (triangular numbers).$q$,$q$20 cubes$q$,'auto','school',true),
  (141,3,$q$5 — Wins = 2 + N, games = 9 + N. Wins are half the games: 2(2 + N) = 9 + N.$q$,$q$Wins = 2 + N, games = 9 + N. Wins are half the games: 2(2 + N) = 9 + N.$q$,$q$5$q$,'auto','school',true),
  (141,4,$q$17 students — List numbers that are 2 more than a multiple of 5: 2, 7, 12, 17 … and find the first that is 1 more than a multiple of 4.$q$,$q$List numbers that are 2 more than a multiple of 5: 2, 7, 12, 17 … and find the first that is 1 more than a multiple of 4.$q$,$q$17 students$q$,'auto','school',true),
